// Replays proto/testdata/payer_mutator_vectors.json (generated by
// proto/go/inject/payer_mutator_vectors_test.go) against
// proto/ts/src/inject/mutators.ts. Results are compared by value, not bytes: Go
// re-marshals, TS splices the original text, and the payer seals whichever it
// produced.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'

import {
  clampMaxOutput,
  dropEmptyTools,
  dropPromptCacheKey,
  dropRoutingPreferences,
  maxOutputFields,
} from '../src/inject/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any
type JsonBody = string | Uint8Array

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
  fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'payer_mutator_vectors.json'), 'utf8'),
) as Json

const utf8 = new TextEncoder()
const text = (b: JsonBody): string => (typeof b === 'string' ? b : new TextDecoder().decode(b))

// Run with both input forms, since each mutator returns the form it was given.
// For bytes, toBe proves an unchanged body came back as the very same object; for
// strings it can only prove equal text.
function checkResult(input: JsonBody, got: JsonBody, c: Json): void {
  expect(typeof got).toBe(typeof input)
  if (!c.changed) {
    expect(got).toBe(input)
    return
  }
  expect(got).not.toBe(input)
  expect(JSON.parse(text(got))).toEqual(JSON.parse(c.want))
}

describe('payer_mutator_vectors.json', () => {
  it('is the schema this test expects', () => {
    expect(v.version).toBe(1)
    for (const k of ['drop_routing_preferences', 'drop_prompt_cache_key', 'drop_empty_tools', 'clamp_max_output']) {
      expect(v[k].length).toBeGreaterThan(0)
    }
  })

  it('agrees on the output-ceiling field names', () => {
    expect(maxOutputFields()).toEqual(v.max_output_fields)
  })

  type Drop = { (b: string): string; (b: Uint8Array): Uint8Array }
  const drops: [string, Drop][] = [
    ['drop_routing_preferences', dropRoutingPreferences],
    ['drop_prompt_cache_key', dropPromptCacheKey],
    ['drop_empty_tools', dropEmptyTools],
  ]
  for (const [key, fn] of drops) {
    describe(key, () => {
      for (const c of v[key]) {
        it(c.name, () => {
          checkResult(c.body, fn(c.body as string), c)
          const bytes = utf8.encode(c.body)
          checkResult(bytes, fn(bytes), c)
        })
      }
    })
  }

  describe('clamp_max_output', () => {
    for (const c of v.clamp_max_output) {
      it(c.name, () => {
        const ceiling = BigInt(c.ceiling)
        const got = clampMaxOutput(c.body, ceiling)
        checkResult(c.body, got.body, c)
        expect(got.requested.toString()).toBe(c.requested)
        const bytes = utf8.encode(c.body)
        const gotBytes = clampMaxOutput(bytes, ceiling)
        checkResult(bytes, gotBytes.body, c)
        expect(gotBytes.requested.toString()).toBe(c.requested)
      })
    }
  })
})

// What the splice keeps that a parse/stringify would lose. Go keeps it too,
// through json.RawMessage, but by-value comparison above can't see it.
describe('payer mutators keep untouched values byte for byte (TS only)', () => {
  it('does not round an integer above 2^53 or reformat a number', () => {
    const body = '{"seed":12345678901234567890,"temperature":0.10,"provider":{},"max_tokens":500}'
    const out = clampMaxOutput(dropRoutingPreferences(body), 100).body
    expect(out).toBe('{"seed":12345678901234567890,"temperature":0.10,"max_tokens":100}')
  })

  it('writes a ceiling above 2^53 exactly', () => {
    const out = clampMaxOutput('{"max_tokens":18446744073709551615}', 9007199254740993n)
    expect(out.body).toBe('{"max_tokens":9007199254740993}')
    expect(out.requested).toBe(18446744073709551615n)
  })

  // Whitespace between entries is not kept: the object is re-joined with bare commas.
  it('keeps the whitespace around the object and inside kept entries', () => {
    expect(dropPromptCacheKey(' { "a" : [ 1 , 2 ] , "prompt_cache_key" : "k" } \n')).toBe(' {"a" : [ 1 , 2 ]} \n')
    expect(dropPromptCacheKey('{"prompt_cache_key":"k"}')).toBe('{}')
  })

  it('handles escaped quotes and brackets inside strings', () => {
    const body = '{"a":"x\\"}]","provider":{"b":"{[\\""},"c":["]"]}'
    expect(dropRoutingPreferences(body)).toBe('{"a":"x\\"}]","c":["]"]}')
  })

  // Go strips the key and keeps the bad byte via json.RawMessage. Refusing to
  // edit would let prompt_cache_key or provider reach the node.
  it('edits a body carrying invalid UTF-8 and passes the bad bytes through', () => {
    const bad = (prefix: string) => new Uint8Array([...utf8.encode(prefix), 0xff, 0xfe, ...utf8.encode('"}')])
    const want = bad('{"m":"')
    expect(dropPromptCacheKey(bad('{"prompt_cache_key":"k","m":"'))).toEqual(want)
    expect(dropRoutingPreferences(bad('{"provider":{},"m":"'))).toEqual(want)
    expect(dropEmptyTools(bad('{"tools":[],"tool_choice":"auto","m":"'))).toEqual(want)
    expect(clampMaxOutput(bad('{"max_tokens":500,"m":"'), 100).body).toEqual(bad('{"max_tokens":100,"m":"'))
  })

  // RFC 8259 leaves repeated names to the reader; a first-wins reader would see
  // 500, and a strict one would refuse the body. Go's map round trip keeps one.
  it('keeps only the last occurrence of a repeated key', () => {
    expect(clampMaxOutput('{"max_tokens":500,"max_tokens":200}', 100)).toEqual({
      body: '{"max_tokens":100}',
      requested: 200n,
    })
    expect(dropPromptCacheKey('{"a":1,"prompt_cache_key":"k","a":2}')).toBe('{"a":2}')
  })

  it('returns a plain Uint8Array for a Buffer, typed as one', () => {
    const out = dropRoutingPreferences(Buffer.from('{"provider":{},"a":1}'))
    expect(new TextDecoder().decode(out)).toBe('{"a":1}')
  })

  it('refuses a ceiling outside uint64, and accepts its bounds', () => {
    expect(() => clampMaxOutput('{}', -1)).toThrow(RangeError)
    expect(() => clampMaxOutput('{}', 1n << 64n)).toThrow(RangeError)
    expect(clampMaxOutput('{"max_tokens":5}', 0xffff_ffff_ffff_ffffn).body).toBe('{"max_tokens":5}')
  })
})
